x_938076_backup_0_backup_scripts.script:
WSDLogger.info('Fixscript - WSD - Nov- RSV - Deactivate BRs', 'disabling outdated Business rules - begins');

try {
    //Deactivating Business Rules if not deleted by upgrade
    var businessRules = [
        'a7e05a7453700110d549ddeeff7b123b'
    ];

    rec = new GlideRecord('sys_script');

    businessRules.forEach(function(sysId) {
        if (rec.get(sysId)) {
            rec.active = false;
            rec.update();
        }
    });
} catch (e) {
    WSDLogger.error('Fixscript - WSD - Nov- RSV - Deactivate BRs', 'Failed to deactivate BRs', e);
}


WSDLogger.info('Fixscript - WSD - Nov- RSV - Deactivate BRs', 'disabling outdated Business rules - ends');
